 * Parse a task file into its tasks.
 * @param {string[]} lines - the input lines.
 * @returns {Map<string, {name: string, command: string, needs: string[], reads: string[], writes: string[]}>} the tasks by name, in declaration order.
 */
export function parse(lines) {
  const tasks = new Map()
  const pending = new Map()

  for (let lineNum = 1; lineNum <= lines.length; lineNum++) {
    const raw = lines[lineNum - 1]
    const trimmed = raw.trim()

    // Skip empty lines and comments
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/u)
    if (words.length === 0) continue

    const directive = words[0]

    if (directive === 'task') {
      if (words.length < 3) throw new ParseError(lineNum, 'expected task <name> <word>...')
      const name = words[1]
      if (!isName(name)) throw new ParseError(lineNum, `invalid task name ${name}`)
      if (tasks.has(name)) throw new ParseError(lineNum, `task ${name} is declared twice`)

      const command = words.slice(2).join(' ')
      const task = {
        name,
        command,
        needs: [],
        reads: [],
        writes: [],
      }
      tasks.set(name, task)

      // Apply any pending directives for this task
      if (pending.has(name)) {
        const directives = pending.get(name)
        for (const { dir, paths } of directives) {
          const field = ATTACHING.get(dir).field
          for (const path of paths) {
            if (!task[field].includes(path)) {
              task[field].push(path)
            }
          }
        }
        pending.delete(name)
      }
    } else if (ATTACHING.has(directive)) {
      if (words.length < 3) {
        const usage = ATTACHING.get(directive).word
        throw new ParseError(lineNum, `expected ${directive} <name> <${usage}>...`)
      }
      const name = words[1]
      const paths = words.slice(2)

      // Validate all paths
      for (const path of paths) {
        if (!isPath(path)) throw new ParseError(lineNum, `invalid path ${path}`)
      }

      if (tasks.has(name)) {
        // Task already declared, apply directive immediately
        const field = ATTACHING.get(directive).field
        const task = tasks.get(name)
        for (const path of paths) {
          if (!task[field].includes(path)) {
            task[field].push(path)
          }
        }
      } else {
        // Task not yet declared, store pending directive
        if (!pending.has(name)) {
          pending.set(name, [])
        }
        pending.get(name).push({ dir: directive, paths })
      }
    } else if (directive === 'needs') {
      if (words.length < 3) throw new ParseError(lineNum, 'expected needs <name> <dependency>...')
      const name = words[1]
      const dependencies = words.slice(2)

      if (tasks.has(name)) {
        // Task already declared, apply directive immediately
        const task = tasks.get(name)
        for (const dep of dependencies) {
          if (!task.needs.includes(dep)) {
            task.needs.push(dep)
          }
        }
      } else {
        // Task not yet declared, store pending directive
        if (!pending.has(name)) {
          pending.set(name, [])
        }
        pending.get(name).push({ dir: 'needs', paths: dependencies })
      }
    } else {
      throw new ParseError(lineNum, `unknown directive ${directive}`)
    }
  }

  // Check for unknown tasks referenced in needs/reads/writes
  for (const task of tasks.values()) {
    for (const dep of task.needs) {
      if (!tasks.has(dep)) throw new ParseError(0, `unknown task ${dep}`)
    }
  }

  return tasks
}"}

